// VIOLA SRP: 5 responsabilidades, 5 razões para mudar
class UserManager {
  // Razão 1: Validação muda
  async createUser(email, password, name) {
    if (!email.includes('@')) throw new Error('Invalid email');
    if (password.length < 8) throw new Error('Password too short');

    // Razão 2: Criptografia muda (bcrypt -> Argon2)
    const hashedPassword = bcrypt.hash(password);

    // Razão 3: Persistência muda
    const user = { email, hashedPassword, name };
    db.insert('users', user);

    // Razão 4: E-mail muda (SMTP -> SendGrid)
    emailService.send(email, 'Welcome!');

    // Razão 5: Analytics muda
    analytics.log('user_created', { userId: user.id });

    return user;
  }
}

// PROBLEMA: Mudança em qualquer responsabilidade afeta a classe inteira.
// Teste precisa de mocks para: validação, cripto, DB, email, analytics.

// SEGUE SRP: Cada classe, uma responsabilidade

class UserValidator {
  validate(data) {
    const errors = [];
    if (!data.email.includes('@')) errors.push('Invalid email');
    if (data.password.length < 8) errors.push('Password too short');
    if (!data.name) errors.push('Name required');
    return { isValid: errors.length === 0, errors };
  }
}

class PasswordHasher {
  hash(password) { return bcrypt.hashSync(password, 10); }
  verify(password, hash) { return bcrypt.compareSync(password, hash); }
}

class UserRepository {
  async create(user) { return await db.insert('users', user); }
  async findByEmail(email) { return await db.findOne('users', { email }); }
}

class WelcomeEmailService {
  async send(user) {
    await emailService.send(user.email, {
      subject: 'Welcome!',
      template: 'welcome',
      data: { name: user.name }
    });
  }
}

class UserAnalyticsService {
  log(event, data) { analytics.log(event, data); }
}

// ORQUESTRAÇÃO: Cada responsabilidade separada
class UserService {
  constructor(validator, passwordHasher, repository, emailService, analyticsService) {
    this.validator = validator;
    this.passwordHasher = passwordHasher;
    this.repository = repository;
    this.emailService = emailService;
    this.analyticsService = analyticsService;
  }

  async createUser(data) {
    // 1. Validar
    const validation = this.validator.validate(data);
    if (!validation.isValid) throw new ValidationError(validation.errors);

    // 2. Hash senha
    const hashedPassword = this.passwordHasher.hash(data.password);

    // 3. Persistir
    const user = await this.repository.create({
      email: data.email,
      password: hashedPassword,
      name: data.name
    });

    // 4. Notificar (async, não bloqueia)
    this.emailService.send(user).catch(error => {
      console.error('Failed to send welcome email', error);
    });

    // 5. Registrar evento
    this.analyticsService.log('user_created', { userId: user.id });

    return user;
  }
}

// BENEFÍCIO: Mudança em qualquer responsabilidade afeta só sua classe.
// Teste pode testar cada um isoladamente, ou UserService com mocks.

// ANTES (viola SRP): Teste precisa de muitos mocks
test('UserManager should create user', () => {
  const mockDB = mock(Database);
  const mockEmail = mock(EmailService);
  const mockAnalytics = mock(AnalyticsService);

  const manager = new UserManager(mockDB, mockEmail, mockAnalytics);
  manager.createUser('test@test.com', 'password123', 'John');

  expect(mockDB.insert).toHaveBeenCalled();
  expect(mockEmail.send).toHaveBeenCalled();
  expect(mockAnalytics.log).toHaveBeenCalled();
  // Teste mistura múltiplas responsabilidades
});

// DEPOIS (segue SRP): Testes isolados, simples

// Testar validação (nenhum mock)
test('UserValidator should reject invalid email', () => {
  const validator = new UserValidator();
  const result = validator.validate({ email: 'invalid', password: 'pass123', name: 'John' });
  expect(result.isValid).toBe(false);
  expect(result.errors).toContain('Invalid email');
});

// Testar hashing (nenhum mock)
test('PasswordHasher should hash and verify', () => {
  const hasher = new PasswordHasher();
  const hash = hasher.hash('password123');
  expect(hasher.verify('password123', hash)).toBe(true);
  expect(hasher.verify('wrongpassword', hash)).toBe(false);
});

// Testar service (mocks de dependências, não de múltiplas responsabilidades)
test('UserService should create user and send email', async () => {
  const mockRepository = mock(UserRepository);
  const mockEmailService = mock(WelcomeEmailService);

  const service = new UserService(
    new UserValidator(),
    new PasswordHasher(),
    mockRepository,
    mockEmailService,
    new UserAnalyticsService()
  );

  await service.createUser({ email: 'test@test.com', password: 'password123', name: 'John' });

  expect(mockRepository.create).toHaveBeenCalled();
  expect(mockEmailService.send).toHaveBeenCalled();
});

