// Esses padrões não são "inventados"; eles emergem naturalmente
// quando aplicamos SRP. É reconhecimento de estrutura útil.

// SITUAÇÃO 1: Prototipagem
// Na prototipagem rápida, está OK ter tudo junto
class QuickLessonAPI {
  async handleGetLesson(req, res) {
    const lessonData = await db.query('SELECT * FROM lessons WHERE id = ?', req.params.id);
    const html = `<div>${lessonData.content}</div>`;
    res.send(html);
  }
}
// Quando protótipo vira produção, refatore. Separação prematura é desperdiço.

// SITUAÇÃO 2: Classes Muito Pequenas
// Email é tão pequeno que separar Validator é overhead
class Email {
  to: string;
  subject: string;
  body: string;

  validate(): boolean {
    return this.to.includes('@') && this.subject && this.body;
  }
}
// Email tem uma responsabilidade: representar um e-mail validado.
// Validação é parte integral da representação.

// SITUAÇÃO 3: Conceitos Intrinsecamente Acoplados
// Login: autenticação + sessão são inseparáveis
class AuthenticationService {
  authenticate(email, password): Session {
    const user = this.findUser(email);
    if (!this.passwordHasher.verify(password, user.passwordHash)) {
      throw new AuthenticationError();
    }
    return this.sessionService.createSession(user);
  }
}
// Separar em PasswordVerifier + SessionCreator adiciona complexidade sem valor.
// Juntas, têm uma razão para mudar: "requisitos de autenticação mudaram"

// TESTE DE SRP: "Se só quero usar Y, posso remover X?"
// Autenticação: "Se só quero verificar senha, preciso de sessão?" -> NÃO.
// Resultado: Pode separar.
// 
// Email: "Se só quero e-mail, preciso de validação?" -> SIM, é parte integral.
// Resultado: Juntos é correto.

