class OrderProcessor {
  async processOrder(order) {
    // Validação
    if (order.items.length === 0) throw new Error('No items');
    if (order.total < 0) throw new Error('Invalid total');

    // Cálculo de imposto
    const tax = order.total * 0.1;

    // Cobrança
    const chargeResult = await stripe.charge(order.total + tax, order.cardToken);

    // Auditoria
    await auditLog.record(`Order processed: ${order.id}`);

    // E-mail de confirmação
    await emailService.send(order.user.email, 'Order confirmed');

    return chargeResult;
  }
}

